#!/usr/bin/env node
// Registers recorded narration files in js/engine/audio-manifest.js (DECISIONS D3, D21).
//
//   node tools/build-audio-manifest.js                scan assets/audio/ and rewrite the manifest
//   node tools/build-audio-manifest.js --todo [--force] [--only PREFIX]
//                                                     print lines that still need a recording (id<TAB>hash<TAB>text)
//   node tools/build-audio-manifest.js --generated FILE
//                                                     FILE has id<TAB>hash lines just made by tools/generate-audio.sh:
//                                                     note them in assets/audio/cues-generated.json, then rebuild
//   node tools/build-audio-manifest.js --accept all|ID...
//                                                     the files for these ids match today's text (you re-recorded them)
//
// A file is assets/audio/<id>.<mp3|m4a|webm|ogg|wav>; if there are several for one id, the first in that order wins.
// Each manifest entry stores the hash of the text the file was recorded from. The narrator plays the file only while
// that hash equals the hash of the lesson's current text, so a changed line falls back to the browser voice until it
// is recorded again. Where the hash comes from, in order:
//   1. the newest cue sheet entry for the id: assets/audio/*.json with kind "numsys-narration-cues" (the #/record page
//      saves one; tools/generate-audio.sh and --accept keep cues-generated.json),
//   2. the hash already in the manifest for that id,
//   3. otherwise the file is new: it is assumed to match today's text (and the tool says so).
'use strict';

const fs = require('fs');
const path = require('path');
const { loadApp, ROOT } = require('../tests/load-app');

const AUDIO_DIR = path.join(ROOT, 'assets', 'audio');
const MANIFEST = path.join(ROOT, 'js', 'engine', 'audio-manifest.js');
const GENERATED_CUES = path.join(AUDIO_DIR, 'cues-generated.json');
const EXTS = ['mp3', 'm4a', 'webm', 'ogg', 'wav'];
const CUE_KIND = 'numsys-narration-cues';

// ---------------------------------------------------------------- pure-ish helpers (tested in tests/tools.test.js)

// Read the current manifest file -> {id: {src, hash}} (no DOM; runs the file in a tiny sandbox).
function readManifest(file) {
  if (!fs.existsSync(file)) return {};
  const sandbox = {};
  sandbox.window = sandbox;
  require('vm').runInNewContext(fs.readFileSync(file, 'utf8'), sandbox, { filename: file });
  return JSON.parse(JSON.stringify((sandbox.NumSys && sandbox.NumSys.audioManifest) || {})); // plain objects from this realm
}

function renderManifest(entries) {
  const ids = Object.keys(entries).sort();
  const body = ids.length
    ? '{\n' + ids.map((id) => `    ${JSON.stringify(id)}: { "src": ${JSON.stringify(entries[id].src)}, "hash": ${JSON.stringify(entries[id].hash)} }`).join(',\n') + '\n  }'
    : '{}';
  return [
    '// Recorded narration files (DECISIONS D3, D21). GENERATED by tools/build-audio-manifest.js: do not edit by hand.',
    '// Maps a narration id (<lesson>.<scene>.<step>) to {src, hash}:',
    '//   src:  relative path, e.g. "assets/audio/binary.switches.0.mp3"',
    '//   hash: NS.narrator.hashText(text) of the narration the file was recorded from. When the lesson text changes the',
    '//         hash no longer matches and the narrator falls back to speech. Empty = every line uses the browser voice.',
    '(function (NS) {',
    "  'use strict';",
    `  NS.audioManifest = ${body};`,
    "})(typeof window !== 'undefined' ? (window.NumSys = window.NumSys || {})",
    "                                 : (globalThis.NumSys = globalThis.NumSys || {}));",
    ''
  ].join('\n');
}

// Audio files in `dir` grouped by id: {id: 'file.ext'} (preferred extension wins).
function scanAudio(dir) {
  const byId = {};
  if (!fs.existsSync(dir)) return byId;
  for (const name of fs.readdirSync(dir)) {
    const m = /^(.+)\.([a-z0-9]+)$/i.exec(name);
    if (!m || EXTS.indexOf(m[2].toLowerCase()) === -1) continue;
    const id = m[1];
    const rank = EXTS.indexOf(m[2].toLowerCase());
    if (!byId[id] || rank < EXTS.indexOf(byId[id].split('.').pop().toLowerCase())) byId[id] = name;
  }
  return byId;
}

// Newest cue per id from every cue sheet in `dir`: {id: {hash, at}}.
function readCues(dir) {
  const cues = {};
  if (!fs.existsSync(dir)) return cues;
  for (const name of fs.readdirSync(dir).filter((n) => n.endsWith('.json')).sort()) {
    let sheet;
    try { sheet = JSON.parse(fs.readFileSync(path.join(dir, name), 'utf8')); } catch (e) { continue; }
    if (!sheet || sheet.kind !== CUE_KIND || !Array.isArray(sheet.lines)) continue;
    for (const line of sheet.lines) {
      if (!line || !line.id || !line.hash) continue;
      const at = Date.parse(line.recordedAt || sheet.recordedAt || 0) || 0;
      if (!cues[line.id] || at >= cues[line.id].at) cues[line.id] = { hash: String(line.hash), at };
    }
  }
  return cues;
}

// The new manifest + a report. lines: [{id, text, hash}] (narration-export), files: scanAudio(), old: readManifest(),
// cues: readCues(), accept: Set of ids (or 'all') whose files match today's text.
function build({ lines, files, old, cues, accept }) {
  const byId = {};
  lines.forEach((l) => { byId[l.id] = l; });
  const entries = {};
  const report = { fresh: [], stale: [], assumed: [], unknown: [], missing: [] };
  Object.keys(files).sort().forEach((id) => {
    const line = byId[id];
    if (!line) { report.unknown.push(files[id]); return; }
    let hash;
    if (accept && (accept === 'all' || accept.has(id))) hash = line.hash;
    else if (cues[id]) hash = cues[id].hash;
    else if (old[id] && old[id].hash) hash = old[id].hash;
    else { hash = line.hash; report.assumed.push(id); }
    entries[id] = { src: 'assets/audio/' + files[id], hash };
    (hash === line.hash ? report.fresh : report.stale).push(id);
  });
  lines.forEach((l) => { if (!entries[l.id]) report.missing.push(l.id); });
  return { entries, report };
}

// Lines that need a (new) recording: no file, or a file recorded from different text.
function todo(lines, entries, opts) {
  opts = opts || {};
  return lines.filter((l) => {
    if (opts.only && l.id.indexOf(opts.only) !== 0) return false;
    if (opts.force) return true;
    return !entries[l.id] || entries[l.id].hash !== l.hash;
  });
}

function mergeGenerated(file, done, when) {
  let sheet = { kind: CUE_KIND, version: 1, recordedAt: when, lines: [] };
  if (fs.existsSync(file)) {
    try { sheet = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { /* start over */ }
  }
  const keep = (sheet.lines || []).filter((l) => !done.some((d) => d.id === l.id));
  sheet.kind = CUE_KIND;
  sheet.recordedAt = when;
  sheet.lines = keep.concat(done.map((d) => ({ id: d.id, hash: d.hash, recordedAt: when })))
    .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return JSON.stringify(sheet, null, 2) + '\n';
}

// ---------------------------------------------------------------- CLI

function argValue(args, name) {
  const i = args.indexOf(name);
  return i === -1 ? null : args[i + 1];
}

function main() {
  const args = process.argv.slice(2);
  const { NumSys } = loadApp();
  const lines = NumSys.movie.helpers.narrationLines().map((l) => ({ id: l.id, text: l.text, hash: NumSys.narrator.hashText(l.text) }));

  if (args.includes('--generated')) {
    const file = argValue(args, '--generated');
    const done = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map((row) => {
      const [id, hash] = row.split('\t');
      return { id, hash };
    });
    fs.mkdirSync(AUDIO_DIR, { recursive: true });
    if (done.length) fs.writeFileSync(GENERATED_CUES, mergeGenerated(GENERATED_CUES, done, new Date().toISOString()));
  }

  let accept = null;
  if (args.includes('--accept')) {
    const rest = args.slice(args.indexOf('--accept') + 1).filter((a) => a.indexOf('--') !== 0);
    accept = rest[0] === 'all' ? 'all' : new Set(rest);
  }

  const files = scanAudio(AUDIO_DIR);
  if (accept) {
    // Remember the decision: note the accepted ids (that have a file) like freshly generated ones.
    const done = lines.filter((l) => files[l.id] && (accept === 'all' || accept.has(l.id))).map((l) => ({ id: l.id, hash: l.hash }));
    if (done.length) fs.writeFileSync(GENERATED_CUES, mergeGenerated(GENERATED_CUES, done, new Date().toISOString()));
  }
  const { entries, report } = build({ lines, files, old: readManifest(MANIFEST), cues: readCues(AUDIO_DIR), accept });

  if (args.includes('--todo')) {
    const list = todo(lines, entries, { force: args.includes('--force'), only: argValue(args, '--only') });
    process.stdout.write(list.map((l) => `${l.id}\t${l.hash}\t${l.text.replace(/\s+/g, ' ')}`).join('\n') + (list.length ? '\n' : ''));
    return;
  }

  fs.writeFileSync(MANIFEST, renderManifest(entries));
  const n = Object.keys(entries).length;
  let bytes = 0;
  Object.keys(entries).forEach((id) => { bytes += fs.statSync(path.join(ROOT, entries[id].src)).size; });
  console.log(`build-audio-manifest: ${n} file(s) registered (${(bytes / 1048576).toFixed(1)} MB), ` +
    `${report.fresh.length} up to date, ${report.stale.length} stale, ${report.missing.length} of ${lines.length} lines have no recording.`);
  if (report.assumed.length) console.log(`  new files assumed to match today's text: ${report.assumed.join(', ')}`);
  if (report.stale.length) {
    console.log(`  stale (the text changed; the browser voice is used until re-recorded): ${report.stale.join(', ')}`);
    console.log('  If you did record these from the new text, run: node tools/build-audio-manifest.js --accept ' + report.stale.join(' '));
  }
  if (report.unknown.length) console.log(`  ignored (no narration line has this id): ${report.unknown.join(', ')}`);
  const unsafe = Object.keys(entries).filter((id) => /\.(webm|ogg)$/i.test(entries[id].src));
  if (unsafe.length) {
    console.log(`  note: ${unsafe.length} file(s) are .webm/.ogg, which older Safari cannot play (it then uses the browser voice). ` +
      'tools/generate-audio.sh --convert turns them into mp3 if ffmpeg is installed.');
  }
}

module.exports = { readManifest, renderManifest, scanAudio, readCues, build, todo, mergeGenerated, EXTS, CUE_KIND };

if (require.main === module) main();
